(* [comment removed for export] *)
Ltac arr_sh A off E :=
  lazymatch goal with
  | UA : u8arr asegs ?mm A ?bs, UAL : Z.of_nat (length ?bs) = _ |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    let SOK := fresh "SOK" in
    pose proof (u8arr_store_okN mm A bs off 2%nat (wa E) UA ltac:(lia) ltac:(lia) ltac:(f_equal; lia)) as SOK;
    zstep;
    lazymatch goal with |- evt _ _ (MS _ _ _ _ _ (write_to_mem mm (Z_to_bv 64 ?E') ?ws) _) =>
      let N := fresh "UA" in let NL := fresh "UAL" in
      assert (N : u8arr asegs (write_to_mem mm (wa E') ws) A (upd_bytes bs (Z.to_nat off) ws))
        by (replace E' with (A + off) by lia; apply (u8arr_writeN mm A bs off ws UA); [lia| rewrite ?length_le2; lia]);
      assert (NL : Z.of_nat (length (upd_bytes bs (Z.to_nat off) ws)) = Z.of_nat (length bs)) by (rewrite upd_bytes_length; [reflexivity| rewrite ?length_le2; lia]);
      rewrite UAL in NL; clear UA UAL; store_done; rename N into UA; rename NL into UAL;
      let bs' := fresh "dbs" in set (bs' := upd_bytes bs (Z.to_nat off) ws) in *; clearbody bs'; try clear bs
    end
  end.

